import math

# Define N and the endpoint K
N_plus_1 = 87  # Size of the set {t0, ..., t86}
K = 171

# Calculate the uniform spacing factor d
d = K / (N_plus_1 - 1)

# Generate the sequence t_i using rounding
t = [round(i * d) for i in range(N_plus_1)]

# Verification: t[0] must be 0, t[86] must be 171
if t[0] != 0 or t[-1] != K:
    print(f"Error in sequence generation: t[0]={t[0]}, t[-1]={t[-1]}")
else:
    print(f"Sequence generated successfully. t_86 = {t[-1]}")

# Calculate the sumset S = {t_i + t_j | 0 <= i <= j <= 86}
sumset = set()
for i in range(N_plus_1):
    for j in range(i, N_plus_1):
        sumset.add(t[i] + t[j])

print(f"Size of the sumset: {len(sumset)}")

